internal sealed class Full62Document : IScribeDocumentDefinition
{
 public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create("Full original 6.2 on actual numbered bilateral paths.", H("Original theorem 6.2"), Blocks(Describe.Lean(DescribeId.Create("original-full-theorem-6-2"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/OriginalAlignedBalanced/Full62.full_original_6_2"), H("Full original theorem 6.2"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The theorem retains the complete general actual-edge statement and the original CompatibleCertificate statement. Essential matrices A and B, arbitrary original R and S, and the original positive lag and bijections remain unchanged. No alignment, balance, second long compatibility equation or pre-assumed conjugacy is added.")),
Paragraph(Text("Clause 6.2.1 uses the same actual C=c.squareMatrix and c.squareFiberEquiv. Explicit leftFiber and rightFiber equivalences retain numbered endpoints and readouts, giving the original incoming and outgoing counts. ActualIncoming.iso transports a supplied actual C edge through its unique lift and inverse numbering equations, rather than replacing edges by their counts.")),
Paragraph(Text("Clause 6.2.2 constructs PA and PB on the same bilateral C space from the existing incoming-lift theorem. Reversal on both ends gives PB on the original B carrier. The homeomorphism is h=PB composed with PA inverse, with inverse PA composed with PB inverse, actual signed shift laws and product/subspace continuity.")),
Paragraph(Text("Clauses 6.2.3 and 6.2.4 identify the same R-edge state using G1 on the actual finite Edge R histories. The left state is the first R factor of psiA inverse on the future A window. The right state is the second R factor of psiB inverse on the reversed dependent window, on the original B carrier. Square reconstruction then gives phi and inverse phi on the very same square.")),
Paragraph(Text("G2 gives the exact future word x(i),...,x(i+m-1). G3 together with G2 gives the original B past word y(i-m),...,y(i-1); the signed formula is reverse(List.ofFn(j : Fin m => y(i-j-1))). Both retain actual numbered edges.")),
Paragraph(Text("Clauses 6.2.5 and 6.2.6 choose least natural forgetting depths with Nat.find, including depth zero, bounded by m. The inverse windows are inclusive [i,i+dL] and [i-dR,i]. For every N including zero, supports [-N,N+dL] and [-N-dR,N] control the centered target interval. Both actual centered escape sets are empty at moduli N+dL and N+dR.")),
Paragraph(Text("The retained consumers certificate_formulas, whole_certificate and full_original_6_2 have content after all same-delivery helpers are inlined: G1, G2 and G3 remain on their live proof paths. Escape registration for all 30 current public theorem targets remains unfinished under issue 19240, with zero declared_validated; parent 8336 remains open."))), DescribeRole.Theorem))));
}
